-- 011_seed_example_museum.sql
-- Complete three-floor example museum for local development and demos.
-- Run after migrations 001-010.

-- Keep this seed compatible with databases that stopped before migration 010.
ALTER TABLE map_nodes ADD COLUMN IF NOT EXISTS artifact_id UUID REFERENCES artifacts(id) ON DELETE SET NULL;
ALTER TABLE map_nodes ADD COLUMN IF NOT EXISTS is_must_visit BOOLEAN DEFAULT FALSE;
ALTER TABLE map_nodes ADD COLUMN IF NOT EXISTS latitude DOUBLE PRECISION;
ALTER TABLE map_nodes ADD COLUMN IF NOT EXISTS longitude DOUBLE PRECISION;
ALTER TABLE map_nodes ADD COLUMN IF NOT EXISTS is_manually_corrected BOOLEAN DEFAULT FALSE;
ALTER TABLE map_edges ADD COLUMN IF NOT EXISTS edge_type TEXT DEFAULT 'normal';
ALTER TABLE floor_plans ADD COLUMN IF NOT EXISTS affine_transform JSONB;

-- Floor plans
ON CONFLICT (id) DO UPDATE SET
    name = EXCLUDED.name,
    floor_number = EXCLUDED.floor_number,
    image_url = EXCLUDED.image_url,
    width_px = EXCLUDED.width_px,
    height_px = EXCLUDED.height_px,
    scale_meters_per_px = EXCLUDED.scale_meters_per_px;

-- Georeferencing anchors around the example museum site.
SELECT plans.id, anchors.map_x, anchors.map_y, anchors.latitude, anchors.longitude
FROM (VALUES
    ('e1000000-0000-0000-0000-000000000001'::uuid, 0.05, 0.05, 51.50740, -0.12780),
    ('e1000000-0000-0000-0000-000000000001'::uuid, 0.95, 0.05, 51.50740, -0.12720),
    ('e1000000-0000-0000-0000-000000000002'::uuid, 0.05, 0.05, 51.50740, -0.12780),
    ('e1000000-0000-0000-0000-000000000002'::uuid, 0.95, 0.05, 51.50740, -0.12720),
    ('e1000000-0000-0000-0000-000000000003'::uuid, 0.05, 0.05, 51.50740, -0.12780),
    ('e1000000-0000-0000-0000-000000000003'::uuid, 0.95, 0.05, 51.50740, -0.12720)
) AS anchors(floor_plan_id, map_x, map_y, latitude, longitude)
JOIN floor_plans plans ON plans.id = anchors.floor_plan_id
WHERE NOT EXISTS (
    SELECT 1 FROM map_anchors existing
    WHERE existing.floor_plan_id = anchors.floor_plan_id
      AND existing.map_x = anchors.map_x
      AND existing.map_y = anchors.map_y
);

-- Exhibit records used by exhibit nodes.
ON CONFLICT (id) DO NOTHING;

-- Navigation nodes. Coordinates are pixels, matching each floor plan's dimensions.
ON CONFLICT (id) DO NOTHING;

-- Walkable graph, including elevator connections between all floors.
ON CONFLICT (id) DO NOTHING;

-- QR entry points for the demo's most useful starting locations.
ON CONFLICT (qr_payload) DO NOTHING;

-- Seven-room first-floor plan matching the supplied residential layout image.
-- Coordinates are normalized to the 1400x900 floor-plan image.
ON CONFLICT (id) DO UPDATE SET
    floor_plan_id = EXCLUDED.floor_plan_id,
    name = EXCLUDED.name,
    room_type = EXCLUDED.room_type,
    walkable = EXCLUDED.walkable;

-- Keep reruns deterministic when the room geometry is edited in this fixture.
DELETE FROM doorway_openings
WHERE room_id IN (
    'e5000000-0000-0000-0000-000000000001', 'e5000000-0000-0000-0000-000000000002',
    'e5000000-0000-0000-0000-000000000003', 'e5000000-0000-0000-0000-000000000004',
    'e5000000-0000-0000-0000-000000000005', 'e5000000-0000-0000-0000-000000000006',
    'e5000000-0000-0000-0000-000000000007'
);
DELETE FROM room_boundaries
WHERE room_id IN (
    'e5000000-0000-0000-0000-000000000001', 'e5000000-0000-0000-0000-000000000002',
    'e5000000-0000-0000-0000-000000000003', 'e5000000-0000-0000-0000-000000000004',
    'e5000000-0000-0000-0000-000000000005', 'e5000000-0000-0000-0000-000000000006',
    'e5000000-0000-0000-0000-000000000007'
);



ON CONFLICT (id) DO NOTHING;

ON CONFLICT (id) DO NOTHING;